 function queuePageHTML(){const blocks=list('goal').filter(g=>!g.closed&&!g.date),tasks=queueTasks();return blocks.length||tasks.length?`${blocks.length?`<section class="section queue-blocks"><div class="heading"><h2>Блоки</h2><span>${blocks.length}</span></div>${blocks.map(queueBlock).join('')}</section>`:''}${section('Задачи',tasks)}`:emptyState('Здесь дела без выбранного дня','Добавь задачу сейчас, а дату можно выбрать позже.','add','Добавить задачу');}
