 function projectsHTML(){const projects=list('project');return `${projects.length>1?button('projects-sort',ui.projectSorting?'Готово':'Изменить порядок',`class="secondary" aria-pressed="${!!ui.projectSorting}"`):''}<div class="project-grid">${projects.map((p,index)=>{const tasks=list('task').filter(t=>projectOf(t)?.id===p.id&&!t.done);return `<div class="project-item">${button('project',`<span class="mark" style="color:${colors[p.color]||colors.graphite}">${projectMark(p)}</span><strong>${esc(p.title)}</strong><span class="quiet">${list('goal').filter(g=>g.projectId===p.id&&!g.closed).length} ${plural(list('goal').filter(g=>g.projectId===p.id&&!g.closed).length,['блок','блока','блоков'])} · ${tasks.length} ${plural(tasks.length,['задача','задачи','задач'])}</span>`,`class="project-tile" data-id="${p.id}"`)}${ui.projectSorting?`<div class="project-order-controls">${button('project-order',icon('left',18),`class="secondary project-up" data-id="${p.id}" data-offset="-1" aria-label="Поднять проект ${attrs(p.title)}" ${index===0?'disabled':''}`)}${button('project-order',icon('right',18),`class="secondary project-down" data-id="${p.id}" data-offset="1" aria-label="Опустить проект ${attrs(p.title)}" ${index===projects.length-1?'disabled':''}`)}</div>`:''}</div>`;}).join('')}</div>${!projects.length?'<div class="empty">Здесь будут твои проекты.<br>Создай первый, когда захочешь объединить задачи.</div>':''}${button('project',`<span>Без проекта</span><span class="trailing">${list('task').filter(t=>!projectOf(t)&&!t.done).length}</span>`,'class="menu-link" data-id=""')}${button('project-new',icon('plus',18)+'Новый проект','class="secondary section"')}`;}
