 function searchResults(){const q=ui.searchQuery.trim();if(!q)return '<p class="empty">Ищи задачи, проекты, покупки и записи «Хочу». Область можно выбрать выше.</p>';const found=searchContents(all(),q,ui.searchScope);return `<p class="quiet search-count" role="status">${found.length?'Найдено: '+found.length:'Ничего не найдено'}</p>${found.length?`<div class="search-list">${found.slice(0,ui.searchLimit).map(e=>{if(e.kind==='task'){const date=e.done?e.completedDate:dateOf(e);return `<article class="search-result"><div class="search-context">${date?button('search-day',esc((e.done?'Сделано · ':'')+dateLong(date)),`data-date="${date}"`):'<span>Без даты</span>'}</div>${taskRow(e)}</article>`;}const labels={project:'Проект',goal:'Блок задач',shopping:'Покупка',wish:'Хочу'},action=e.kind==='wish'?'wish-open':e.kind==='shopping'?'search-shopping':e.kind==='goal'?'goal':'project';return button(action,`<span>${esc(e.title||e.productTitle||labels[e.kind])}<small>${labels[e.kind]}${e.done?' · готово':''}</small></span>${icon('right',17)}`,`class="menu-link search-entity" data-id="${e.id}"`);}).join('')}</div>${found.length>ui.searchLimit?button('search-more','Показать ещё','class="secondary section"'):''}`:'<p class="section-empty">Попробуй другое слово или выбери другую область поиска.</p>'}`;}
