 function refreshSteps(){const s=ui.sheet,form=$('#entry-form');s.draft={...s.draft,...readForm()};s.draft.steps||=[];$('#block-steps').innerHTML=stepPreview(s);$('.steps-review').textContent='Все шаги · '+s.draft.steps.length;const cancel=form.querySelector('[data-action=step-cancel]');if(cancel)cancel.hidden=!Number.isInteger(s.draft.editingStep);form.elements.pendingStep.value=s.draft.pendingStep||'';form.elements.pendingStep.placeholder=Number.isInteger(s.draft.editingStep)?'Изменение шага '+(s.draft.editingStep+1):'Задача '+(s.draft.steps.length+1);for(const b of form.querySelectorAll('[data-action=steps-page]'))b.disabled=Number(b.dataset.value)<0?s.stepPage<=0:s.stepPage+stepCapacity()>=s.draft.steps.length;captureFormDraft(form);}
 function editStep(index){const s=ui.sheet,f=$('#entry-form');if(f.elements.pendingStep.value.trim())confirmStep();s.draft.editingStep=index;s.draft.pendingStep=s.draft.steps[index];f.elements.pendingStep.value=s.draft.pendingStep;refreshSteps();requestAnimationFrame(()=>f.elements.pendingStep.focus({preventScroll:true}));}
 function confirmStep(){const f=$('#entry-form'),s=ui.sheet,text=f.elements.pendingStep?.value.trim();if(!text)return;s.draft={...s.draft,...readForm()};if(Number.isInteger(s.draft.editingStep))s.draft.steps[s.draft.editingStep]=text;else s.draft.steps=[...(s.draft.steps||[]),text];delete s.draft.editingStep;s.draft.pendingStep='';s.stepPage=Math.max(0,s.draft.steps.length-stepCapacity());f.elements.pendingStep.value='';refreshSteps();f.elements.pendingStep.focus({preventScroll:true});}
 function switchEntry(type){captureOpenDrafts();const s=ui.sheet,keepKeyboard=(window.visualViewport?.height||innerHeight)<innerHeight*.8,current={...s.draft,...readForm()};if(type===current.type)return;s.modes||={};s.modes[current.type]=current;s.draft=s.modes[type]||{...current,type,steps:[...(current.steps||[])]};const body=$('.entry-sheet .sheet-body');body.innerHTML=entryBody(s);s.kind=type;s.title=type==='goal'?'Новый блок':'Новая задача';$('.sheet').setAttribute('aria-label',s.title);$('.sheet-head h2').textContent=s.title;restoreFormDraft($('#entry-form'));decorateDraftNotices();captureFormDraft($('#entry-form'));body.scrollTop=0;(keepKeyboard?body.querySelector('textarea'):body.querySelector(`[data-value="${type}"]`))?.focus({preventScroll:true});}
