 function openEntry(id='',preset={}){const e=get(id),type=e?.kind==='goal'||preset.type==='goal'?'goal':'task',defaults={type,title:e?.title||(!id&&type==='task'?prefs.taskDraft:'')||'',date:e?(e.date||''):['day','calendar'].includes(ui.screen)?ui.day:'',time:'',projectId:['project','info'].includes(ui.screen)?ui.projectId:ui.screen==='goal'?get(ui.goalId)?.projectId||'':'',goalId:ui.screen==='goal'?ui.goalId:'',important:false,...e,...preset};if(e?.kind==='task')defaults.projectId=projectOf(e)?.id||'';sheet(e?'Изменить '+(type==='goal'?'блок':'задачу'):(type==='goal'?'Новый блок':'Новая задача'),entryBody,{save:e?'Сохранить':'Добавить',action:'entry-save',draft:defaults,id,kind:type});}
 async function saveEntry(){const s=ui.sheet;if(!s)return;const d={...s.draft,...readForm()},title=String(d.title||'').trim();if(!title){fieldError($('#entry-form'),'title','Напиши название.','form-error');return;}s.draft=d;captureFormDraft($('#entry-form'));let id=s.id,saved=false;
  const values=d.type==='goal'?{title,date:d.date||'',projectId:d.projectId||'',...(!id?{closed:false,closedAt:0,closedDate:''}:{})}:{title,date:d.date||'',time:d.date?d.time||'':'',goalId:d.goalId||'',projectId:d.goalId?'':d.projectId||'',...flagPatch(d.important?(d.flag||'diamond'):''),...(!id?{done:false,completedAt:0,completedDate:''}:{})};
  if(d.type==='goal'&&!id){id='goal_'+crypto.randomUUID();const now=Date.now(),changes=[{id,kind:'goal',patch:{...values,createdAt:now,deleted:false}}];const stepTexts=[...(d.steps||[])];if(d.pendingStep?.trim()){if(Number.isInteger(d.editingStep))stepTexts[d.editingStep]=d.pendingStep;else stepTexts.push(d.pendingStep);}for(const text of stepTexts){const childTitle=String(text).trim();if(childTitle)changes.push({id:'task_'+crypto.randomUUID(),kind:'task',patch:{title:childTitle,goalId:id,projectId:'',date:'',time:'',important:false,done:false,completedAt:0,completedDate:'',createdAt:now+changes.length,deleted:false}});}saved=await perform(changes,'Блок и задачи добавлены');}else if(id)saved=await perform([{id,kind:d.type,patch:values}],'Изменения сохранены');else{ id=await create(d.type,values,'Задача добавлена');saved=!!id;}
  if(!saved)return false;clearFormDraft($('#entry-form'));prefs.taskDraft='';savePrefs();if(s.returnReader){returnToTaskReader(s.returnReader);return;}closeSheet(false);if(d.type==='goal')visit('goal',{goalId:id});else render();
 }
 async function toggleTask(id){const t=get(id);if(!t)return false;const done=!t.done,changes=[{id,kind:'task',patch:{done,completedAt:done?Date.now():0,completedDate:done?dayKey():''}}];const g=get(t.goalId);if(!done&&g?.closed)changes.push({id:g.id,kind:'goal',patch:{closed:false,closedAt:0,closedDate:''}});if(!await perform(changes,done?'Задача выполнена':'Задача возвращена в работу'))return false;closeSheet(false);render();navigator.vibrate?.(8);return true;}
