 function openProject(id=''){const p=get(id)||{title:'',color:'graphite'};sheet(id?'Редактировать проект':'Новый проект',`<form autocomplete="off" id="project-form"><label class="field">Название<input name="title" maxlength="80" value="${attrs(p.title)}" placeholder="Название проекта" required></label><p class="field-help">Полное название видно в проекте. В компактной подписи оно может сокращаться.</p><input name="color" type="hidden" value="${attrs(p.color)}"><div class="color-options">${Object.entries({graphite:'Графит',petrol:'Петроль',blue:'Синий',lime:'Лайм'}).map(([v,l])=>button('project-color',`<i style="background:${colors[v]}"></i>${l}`,`data-value="${v}" aria-pressed="${p.color===v}"`)).join('')}</div><div id="project-error" class="sheet-error" role="alert"></div><button type="submit" class="primary">${id?'Сохранить изменения':'Создать проект'}</button>${id?button('project-delete',icon('trash',17)+'Удалить проект',`data-id="${id}" class="danger project-delete"`):''}</form>`,{id});}
 async function saveProject(){const s=ui.sheet,d=readForm(),title=String(d.title||'').trim();if(!title)return false;if(Array.from(title).length>80){fieldError($('#project-form'),'title','Сократи название до 80 символов.','project-error');return false;}const values={title,symbol:get(s.id)?.symbol||'',color:colors[d.color]?d.color:'graphite',...(!s.id?{info:''}:{})};let id=s.id;if(id){if(!await perform([{id,kind:'project',patch:values}],'Проект сохранён'))return false;}else{id=await create('project',values,'Проект создан');if(!id)return false;}clearFormDraft($('#project-form'));closeSheet(false);visit('project',{projectId:id});return true;}
