 function openWish(id=''){if(!id){sheet('Добавить в Хочу',`<form autocomplete="off" id="wish-quick"><label class="field"><textarea name="text" rows="5" placeholder="Ссылка, название и всё, что хочется добавить от себя" aria-label="Желание" required></textarea></label><div id="wish-quick-error" class="sheet-error" role="alert"></div><button type="submit" class="primary">Добавить в Хочу</button></form>`);return;}const w=get(id)||{title:'',productTitle:'',url:'',image:'',price:0,currency:'RUB',extra:0,estimated:true};sheet(id?'Изменить запись':'Добавить в Хочу',`<form autocomplete="off" id="wish-form"><label class="field">Твой заголовок<textarea name="title" rows="2" placeholder="Например, маме на день рождения">${esc(w.title)}</textarea></label><label class="field">Ссылка · необязательно<input type="url" name="url" value="${attrs(w.url)}" placeholder="https://…"></label><label class="field">Название товара<input name="productTitle" value="${attrs(w.productTitle)}" placeholder="Название модели или товара"></label><label class="field">Мои пометки<textarea name="notes" rows="2" placeholder="Дополнительная информация">${esc(w.notes||'')}</textarea></label><label class="field">Изображение · ссылка<input type="url" name="image" value="${attrs(w.image)}" placeholder="https://…"></label><div class="form-row"><label class="field">Цена<input name="price" inputmode="decimal" value="${w.price||''}" placeholder="0"></label><label class="field">Валюта<select name="currency">${['RUB','EUR','USD','RSD'].map(c=>`<option ${c===(w.currency||'RUB')?'selected':''}>${c}</option>`).join('')}</select></label></div><label class="field">Дополнительно к стоимости<input name="extra" inputmode="decimal" value="${w.extra||''}" placeholder="Например, стоимость линз"></label><label class="check-field"><input type="checkbox" name="estimated" ${w.estimated?'checked':''}>Дополнительная сумма приблизительная</label><div id="form-error" class="sheet-error" role="alert"></div><button type="submit" class="primary">Сохранить запись</button>${id?button('delete','Удалить',`class="danger section" data-id="${id}"`):''}</form>`,{id,save:'Сохранить',action:'wish-save'});}
 function validHTTPS(value){if(!value)return true;try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}}
 async function saveWish(){const s=ui.sheet,d=readForm(),title=String(d.title||'').trim(),productTitle=String(d.productTitle||'').trim(),url=String(d.url||'').trim(),image=String(d.image||'').trim();if(!title&&!productTitle&&!url){$('#form-error').textContent='Добавь название или ссылку.';return;}if(!validHTTPS(url)||!validHTTPS(image)){fieldError($('#wish-form'),!validHTTPS(url)?'url':'image','Нужна полная HTTPS-ссылка.','form-error');return;}const values={title,productTitle,url,image,notes:String(d.notes||'').trim(),price:parseNumber(d.price),currency:d.currency||'RUB',extra:parseNumber(d.extra),estimated:!!d.estimated,...(!s.id?{done:false,completedAt:0}:{}),status:url&&!productTitle?'manual':'ready'};let id=s.id;if(id){if(!await perform([{id,kind:'wish',patch:values}],'Запись сохранена'))return false;}else{id=await create('wish',values,'Добавлено в Хочу');if(!id)return false;}clearFormDraft($('#wish-form'));const target=s.returnWish;closeSheet(false);render();if(target)openWishReader(id,target.origin);return true;}
 const enrichingWishes=new Set();
 async function enrichWish(id,overwrite=false){
  const before=get(id),client=cloud;if(!before?.url||enrichingWishes.has(id))return false;
  if(!client){notify('Для получения данных товара подключи синхронизацию.');return false;}
  if(!navigator.onLine){notify('Получим данные товара после подключения к интернету.');return false;}
  enrichingWishes.add(id);let message='';
  try{
   await atomicStoreMutation(store,()=>{if(get(id)?.url===before.url)store.patch(id,'wish',{status:'loading'});});
   if(!ui.sheet||ui.sheet.kind==='wish-reader')render();
   const result=await client.request('wish-card',[],{url:before.url,refresh:overwrite});
   if(cloud!==client)return false;
   await atomicStoreMutation(store,()=>{const current=get(id),patch=wishMetadataPatch(before,current,result.card,overwrite);if(patch)store.patch(id,'wish',{...patch,status:(patch.productTitle||current.productTitle)&&(patch.image||current.image)&&(patch.price||current.price)?'ready':'partial'});});
   message='Данные товара получены';
  }catch(error){
   message=error.message||'Не удалось получить данные товара. Запись сохранена.';
   try{await atomicStoreMutation(store,()=>{const current=get(id);if(cloud===client&&current?.url===before.url)store.patch(id,'wish',{status:error.code==='WISH_BLOCKED'?'blocked':'manual'});});}catch(storageError){storageFailure(storageError);}
  }finally{enrichingWishes.delete(id);if(!ui.sheet||ui.sheet.kind==='wish-reader')render();scheduleSync();if(message)notify(message);}
  return true;
 }

