 root.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const image=e.target,box=image.closest('.wish-image'),item=image.closest('.wish');if(box)box.hidden=true;else image.remove();if(item){item.classList.remove('has-image');item.classList.add('text-only');}}},true);
 document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!ui.sheet){e.preventDefault();openSearch();return;}
  if(e.key==='Escape'){if(ui.sheet)closeTaskPanel();else if(ui.actionId){ui.actionId='';render();}else if(ui.history.length)goBack();return;}
  if(ui.sheet&&e.target.name==='pendingStep'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();confirmStep();return;}
  if(ui.sheet&&e.key==='Tab'){const focusables=Array.from($('.sheet').querySelectorAll('button:not([disabled]),input:not([disabled]),textarea,select,a[href],[tabindex="0"]')).filter(el=>el.offsetParent!==null);if(!focusables.length)return;const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
  if(isTyping()||ui.sheet)return;
  if(e.altKey&&['ArrowUp','ArrowDown'].includes(e.key)){const row=e.target.closest('[data-row]'),item=row&&get(row.dataset.row);if(['task','goal'].includes(item?.kind)&&!item.done&&!item.closed){e.preventDefault();const group=row.parentElement,rows=[...group.querySelectorAll(':scope > [data-row]')].filter(n=>['task','goal'].includes(get(n.dataset.row)?.kind)&&!get(n.dataset.row)?.done&&!get(n.dataset.row)?.closed),i=rows.indexOf(row),target=rows[i+(e.key==='ArrowUp'?-1:1)];if(target){if(e.key==='ArrowUp')target.before(row);else target.after(row);const ids=[...group.querySelectorAll(':scope > [data-row]')].map(n=>n.dataset.row).filter(id=>['task','goal'].includes(get(id)?.kind)&&!get(id)?.done&&!get(id)?.closed);perform(ids.map((id,n)=>({id,kind:get(id).kind,patch:{order:n+1}})),'Порядок сохранён').then(()=>root.querySelector(`[data-row="${item.id}"] .task-title`)?.focus({preventScroll:true}));}return;}}

  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();}
  else if(!e.metaKey&&!e.ctrlKey&&e.key.toLowerCase()==='n'){e.preventDefault();openEntry();}
  else if(ui.screen==='day'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveDay(addDays(ui.day,e.key==='ArrowRight'?1:-1));}
 });
 async function enableShake(){
  if(!window.DeviceMotionEvent){notify('На этом устройстве используй кнопку «Отменить»');return;}
  try{if(typeof DeviceMotionEvent.requestPermission==='function'){const status=await DeviceMotionEvent.requestPermission();if(status!=='granted'){notify('Разрешение на движение не получено');return;}}if(!shakeEnabled){window.addEventListener('devicemotion',onMotion);shakeEnabled=true;}notify('Отмена встряхиванием включена');render();}catch{notify('Не удалось включить. Кнопка отмены остаётся доступной.');}
 }
 function onMotion(event){const a=event.accelerationIncludingGravity;if(!a||a.x===null)return;const now=Date.now();if(lastAccel){const delta=Math.abs(a.x-lastAccel.x)+Math.abs(a.y-lastAccel.y)+Math.abs(a.z-lastAccel.z);if(delta>24&&now-lastPeak>120){shakePeaks=now-lastPeak<800?shakePeaks+1:1;lastPeak=now;if(shakePeaks>=2&&now-lastShake>2500&&ui.undo.length&&!ui.sheet){lastShake=now;shakePeaks=0;document.activeElement?.blur();window.getSelection()?.removeAllRanges();sheet('Отменить действие?',`<p class="transfer-title">${esc(ui.undo.at(-1).label)}</p>${button('confirm-undo','Отменить последнее действие','class="primary"')}${button('sheet-cancel','Оставить как есть','class="secondary section"')}`);}}}lastAccel={x:a.x,y:a.y,z:a.z};}
 function viewportChanged(){queueTaskPreviewOverflow();const v=window.visualViewport,height=v?.height||innerHeight;const safe=getComputedStyle(root),available=height-(parseFloat(safe.getPropertyValue('--safe-top'))||0)-(parseFloat(safe.getPropertyValue('--safe-bottom'))||0);root.dataset.compactViewport=String(available<440);root.dataset.tinyViewport=String(available<330);root.style.setProperty('--visual-height',height+'px');if(!v)return;root.style.setProperty('--keyboard-inset',Math.max(0,window.innerHeight-v.height-v.offsetTop)+'px');if(ui.sheet?.draft?.type==='goal'&&$('#block-steps'))refreshSteps();}window.visualViewport?.addEventListener('resize',viewportChanged);window.visualViewport?.addEventListener('scroll',viewportChanged);window.addEventListener('resize',viewportChanged);const taskPreviewResize=new ResizeObserver(queueTaskPreviewOverflow);taskPreviewResize.observe(root);viewportChanged();
